const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const rawFrom = String(j.from || j.fromEmail || (j.headers && j.headers.from) || '');
  const m = rawFrom.match(/^(.*?)\s*<(.+?)>\s*$/);
  const from_name = m ? m[1].replace(/^"|"$/g, '').trim() : String(j.fromName || rawFrom).trim();
  const from_email = (m ? m[2] : rawFrom).trim().toLowerCase();
  const mailbox = String(j.label || j.mailbox || 'INBOX');
  const message_id = String(j.messageId || j.id || (j.headers && j.headers['message-id']) || '');
  const thread_id = String(j.threadId || j.thread_id || '') || null;
  const toRaw = j.to || j.toEmail || '';
  const to = Array.isArray(toRaw) ? toRaw.map(String) : String(toRaw).split(',').map(s => s.trim()).filter(Boolean);
  const htmlBody = String(j.textHtml || j.html || '');
  const textBody = String(j.textPlain || j.text || '');
  let body = textBody || htmlBody;
  body = body.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ');
  body = body.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  body = body.split(/\n\s*On .*wrote:/i)[0];
  body = body.split(/\n\s*-{2,}\s*\n/)[0];
  body = body.replace(/\s+/g, ' ').trim();
  const MAX_BODY = 16000;
  const bodyTruncated = body.length > MAX_BODY;
  if (bodyTruncated) body = body.slice(0, MAX_BODY);
  const attachments = Array.isArray(j.attachments) ? j.attachments : [];
  const attachment_metadata = attachments.map(a => ({ filename: String(a.filename || a.name || ''), mimeType: String(a.mimeType || a.type || ''), size: Number(a.size || 0) }));
  const MAX_ATTACH = 10485760;
  const oversized_attachments = attachment_metadata.filter(a => a.size > MAX_ATTACH);
  let h = 0x811c9dc5;
  for (let i = 0; i < body.length; i++) { h ^= body.charCodeAt(i); h = (h * 0x01000193) >>> 0; }
  const content_hash = h.toString(16);
  const idempotency_key = mailbox + ':' + message_id;
  const hex = () => Math.floor((1 + Math.random()) * 0x100000000).toString(16).slice(1);
  const correlation_id = hex() + hex() + '-' + hex() + '-' + hex() + '-' + hex() + '-' + hex() + hex() + hex();
  const received_at = j.receivedDate ? new Date(j.receivedDate).toISOString() : new Date().toISOString();
  const retention_expires_at = new Date(Date.parse(received_at) + 30 * 86400000).toISOString();
  const source_link = thread_id ? 'https://mail.google.com/mail/u/0/#inbox/' + thread_id : null;
  out.push({ json: {
    correlation_id, idempotency_key, mailbox, message_id, thread_id,
    from_name, from_email, to, subject: String(j.subject || '(no subject)'),
    text_body: body, received_at, attachment_metadata, source_link, content_hash,
    body_truncated: bodyTruncated, oversized_attachments, retention_expires_at
  }});
}
return out;

const rec = $('Idempotency Check').first().json || {};
const fields = rec.fields || rec;
return [{ json: {
  outcome: 'duplicate',
  correlation_id: fields.correlation_id || '',
  idempotency_key: fields.idempotency_key || '',
  message_id: fields.message_id || '',
  processing_status: fields.processing_status || 'received',
  draft_id: fields.draft_id || '',
  task_id: fields.task_id || '',
  message: 'Message already processed; no duplicate draft, task, or alert created.'
}}];

const j = $('Normalize & Sanitize Email').item.json;
const config = {
  vip_domains: ['northstar.example', 'acmecorp.example'],
  vip_senders: ['ceo@northstar.example', 'founder@acmecorp.example'],
  newsletter_senders: ['newsletter@updates.example', 'no-reply@mailer.example', 'digest@weekly.example'],
  newsletter_subject_patterns: ['unsubscribe', 'weekly digest', 'newsletter', 'you are invited', 'special offer'],
  blocked_senders: ['spammer@blocked.example', 'phish@blocked.example']
};
const email = (j.from_email || '').toLowerCase();
const subject = (j.subject || '').toLowerCase();
const domain = email.split('@')[1] || '';
let vip = false, newsletter = false, blocked = false, rule = 'proceed';
if (config.blocked_senders.includes(email)) { blocked = true; rule = 'blocked'; }
else {
  if (config.vip_senders.includes(email) || config.vip_domains.includes(domain)) vip = true;
  if (config.newsletter_senders.includes(email) || config.newsletter_subject_patterns.some(p => subject.includes(p))) newsletter = true;
  if (newsletter) rule = 'newsletter';
  else if (vip) rule = 'vip';
}
return [{ json: { ...j, rules: { vip, newsletter, blocked, rule }, proceed: !blocked } }];

const email = $('Prepare Triage Input').item.json;
const triage = $input.first().json || {};
return [{ json: {
  ...email,
  triage: {
    review_required: !!triage.review_required,
    gate_reason: triage.gate_reason || '',
    category: triage.category || '',
    importance: triage.importance || '',
    needs_reply: !!triage.needs_reply,
    needs_task: !!triage.needs_task,
    summary: triage.summary || '',
    draft_reply: triage.draft_reply || '',
    suggested_due_at: triage.suggested_due_at || null,
    confidence: triage.confidence,
    sensitive: !!triage.sensitive,
    safety_reason: triage.safety_reason || null,
    review_queue_id: triage.review_queue_id || ''
  }
}}];
